let watchlist = (_GetWatchlist('pciassets') | project asset);
AzureDiagnostics 
|where Resource in~ (watchlist)
|make-series TotalEvents = count() default = 0 on TimeGenerated from {TimeToken:start} to {TimeToken:end} step {TimeToken:grain};

let watchlist = (_GetWatchlist('pciassets') | project asset);
union Event,Syslog
|where Computer in~ (watchlist)
| make-series TotalEvents = count() default = 0 on TimeGenerated from {TimeToken:start} to {TimeToken:end} step {TimeToken:grain};

let watchlist = (_GetWatchlist('pciassets') | project asset);
let OracleDatabaseAuditEvent_v = view () { Syslog | where ProcessName has 'Oracle' and SyslogMessage has 'ACTION' | extend Action = extract(@'ACTION(?::|\s+:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage), DbAction = extract(@'ACTION(?::|\s+:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage), ReturnCode = toint(extract(@'(?:RETCODE|RETURNCODE)(?::|:\[\d+\]\s*)"(\d+)"', 1, SyslogMessage)), DstUserName = extract(@'DBUSER(?::|:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage), SrcUserName = coalesce(extract(@'CLIENTID:"([^"]+)"', 1, SyslogMessage), extract(@'OS_USER(?::|:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage)), SrcDvcHostname = HostName };
OracleDatabaseAuditEvent_v
|where SrcDvcHostname has_any (watchlist)
| where isnotempty(DbAction)
| where TimeGenerated {TimeRange}
| summarize count() by Action, DbAction, SrcDvcHostname

let watchlist = (_GetWatchlist('pciassets') | project asset);
let OracleDatabaseAuditEvent_v = view () { Syslog | where ProcessName has 'Oracle' and SyslogMessage has 'ACTION' | extend Action = extract(@'ACTION(?::|\s+:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage), DbAction = extract(@'ACTION(?::|\s+:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage), ReturnCode = toint(extract(@'(?:RETCODE|RETURNCODE)(?::|:\[\d+\]\s*)"(\d+)"', 1, SyslogMessage)), DstUserName = extract(@'DBUSER(?::|:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage), SrcUserName = coalesce(extract(@'CLIENTID:"([^"]+)"', 1, SyslogMessage), extract(@'OS_USER(?::|:\[\d+\]\s*)"([^"]+)"', 1, SyslogMessage)), SrcDvcHostname = HostName };
OracleDatabaseAuditEvent_v
|where SrcDvcHostname has_any (watchlist)
| where TimeGenerated {TimeRange}
| where isnotempty(DbAction)
| extend status = iff(ReturnCode == 0, 'Success', 'Failure')
| project TimeGenerated, DstUserName, SrcUserName, DbAction, status, SrcDvcHostname
| sort by TimeGenerated desc

